// Normalize the /news/fetch result and decide the branch (§3.1, §9.4).
// httpRequest onError:continueRegularOutput leaves an `error` object on failure;
// a partial-source failure returns items with a summary prefixed "degraded:".
const fetch = $json;
const trigger = $('When Executed by Another Workflow').first().json;
const httpError = fetch.error !== undefined || fetch.items === undefined;
const items = Array.isArray(fetch.items) ? fetch.items : [];
const summary = (fetch.summary || '').toString();
const degradedFetch = httpError || summary.startsWith('degraded:');
const windowMinutes = Number(trigger.window_minutes) || 120;
return [{ json: {
  ticker: trigger.ticker,
  run_id: trigger.run_id,
  window_minutes: windowMinutes,
  items,
  few_shot: Array.isArray(fetch.few_shot) ? fetch.few_shot : [],
  fetch_summary: summary || (httpError ? 'news fetch failed' : ''),
  has_items: items.length > 0,
  degraded_fetch: degradedFetch,
} }];

// Fetch itself failed/degraded and produced no items (§9.4): no fabrication,
// explicit reason, null aggregates. Risk Manager downgrades conviction.
const c = $('Prep Fetch').first().json;
return [{ json: {
  ticker: c.ticker,
  window: (c.window_minutes / 60) + 'h',
  llm_sentiment: null,
  model_sentiment: null,
  disagreement: null,
  n_articles: 0,
  top_items: [],
  summary: `degraded: ${c.fetch_summary || 'news fetch failed'}`,
  status: 'degraded',
} }];

// Healthy fetch, zero matching articles: a valid "no coverage" result (§13).
// Never padded — neutral scores and an explicit zero article count.
const c = $('Prep Fetch').first().json;
return [{ json: {
  ticker: c.ticker,
  window: (c.window_minutes / 60) + 'h',
  llm_sentiment: 0.0,
  model_sentiment: 0.0,
  disagreement: 0.0,
  n_articles: 0,
  top_items: [],
  summary: `No recent coverage in the last ${c.window_minutes}m.`,
  status: 'ok',
} }];

// Normalize the /sentiment (FinBERT/HeBERT) response. onError leaves `error`;
// the endpoint prefixes its summary with "degraded:" when a model was unavailable.
const resp = $json;
const scores = Array.isArray(resp.scores) ? resp.scores : [];
const summary = (resp.summary || '').toString();
const degraded = resp.error !== undefined || resp.scores === undefined || summary.startsWith('degraded:');
return [{ json: { model_scores: scores, model_summary: summary, model_degraded: degraded } }];

// Build the few-shot LLM scoring prompt (§3.1). Only short text (headline +
// summary) and ids traverse the LLM — never article bodies (§2 guardrail).
// Few-shot examples come from /news/fetch (loaded from prompts/sentiment_examples.jsonl).
const c = $('Prep Fetch').first().json;
const items = c.items;
const fewShot = c.few_shot || [];
const shotLines = fewShot
  .map(e => `- (${e.language}) "${e.text}" => score ${e.score} — ${e.reasoning}`)
  .join('\n');
const articleLines = items
  .map(a => `- id=${a.id} (${a.language}) ${a.headline}${a.summary ? ' — ' + a.summary : ''}`)
  .join('\n');
const prompt = [
  `You are the Sentiment Agent for TA-35 ticker ${c.ticker}.`,
  'Score each news item\'s sentiment toward the company on a -1..+1 scale',
  '(-1 very negative, 0 neutral, +1 very positive). Translate Hebrew inline as needed.',
  '',
  'Labeled examples:',
  shotLines || '(none)',
  '',
  'News items to score:',
  articleLines,
  '',
  'Respond with ONLY a JSON object, no markdown fences, exactly this shape:',
  '{"items":[{"id":"<id>","score":<number -1..1>,"reasoning":"<short, under 300 chars>"}],"summary":"<overall tone, under 500 chars>"}',
  'Include exactly one entry per news id listed above. Base scores only on the text provided.',
].join('\n');
return [{ json: { ticker: c.ticker, run_id: c.run_id, prompt } }];

// Parse the raw LLM text into a candidate payload for POST /validate.
// A parse failure is NOT swallowed — it becomes an invalid payload so the
// validate -> retry -> degraded path handles it (§9.4).
const raw = ($json.text ?? '').toString().trim()
  .replace(/^```(?:json)?\s*/i, '')
  .replace(/```\s*$/, '');
let payload;
try {
  payload = JSON.parse(raw);
} catch (e) {
  payload = { _parse_error: String(e) };
}
if (typeof payload !== 'object' || payload === null || Array.isArray(payload)) {
  payload = { _not_an_object: true };
}
return [{ json: { agent: 'sentiment', payload, raw } }];

// LLM scores passed schema validation — carry the per-article scores forward.
const payload = $('Parse Scores').first().json.payload;
return [{ json: {
  llm_items: payload.items,
  llm_summary: payload.summary || '',
  llm_degraded: false,
  llm_reason: null,
} }];

// One automatic retry with a stricter instruction (§9.4); the /validate errors
// are quoted back to the model.
const base = $('Build LLM Prompt').first().json;
const errors = $json.errors || [];
const prompt = base.prompt
  + '\n\nYour previous response was rejected by schema validation: '
  + JSON.stringify(errors)
  + '\nRespond again with ONLY the JSON object described above — no prose, no markdown '
  + 'fences, no extra keys. Each item score MUST be a number between -1 and 1, with '
  + 'exactly one entry per news id.';
return [{ json: { prompt } }];

// Parse the raw LLM text into a candidate payload for POST /validate.
// A parse failure is NOT swallowed — it becomes an invalid payload so the
// validate -> retry -> degraded path handles it (§9.4).
const raw = ($json.text ?? '').toString().trim()
  .replace(/^```(?:json)?\s*/i, '')
  .replace(/```\s*$/, '');
let payload;
try {
  payload = JSON.parse(raw);
} catch (e) {
  payload = { _parse_error: String(e) };
}
if (typeof payload !== 'object' || payload === null || Array.isArray(payload)) {
  payload = { _not_an_object: true };
}
return [{ json: { agent: 'sentiment', payload, raw } }];

const payload = $('Parse Retry').first().json.payload;
return [{ json: {
  llm_items: payload.items,
  llm_summary: payload.summary || '',
  llm_degraded: false,
  llm_reason: null,
} }];

// LLM scoring failed validation twice — degrade the LLM side only. The model
// (FinBERT/HeBERT) side still contributes; no fabrication (§9.4).
let errors = [];
try { errors = $('Validate Retry').first().json.errors || []; } catch (e) { /* retry never ran */ }
return [{ json: {
  llm_items: null,
  llm_summary: '',
  llm_degraded: true,
  llm_reason: 'LLM scoring failed schema validation after one stricter retry'
    + (errors.length ? ` (${errors.join('; ')})` : ''),
} }];

// Combine the two independent scorers into the §3.1 output and compute the
// disagreement metric. The fired LLM terminal is on $json; the model scores and
// fetch context are pulled by node name so this works regardless of which LLM
// terminal (ok / retry-ok / degraded) executed.
const c = $('Prep Fetch').first().json;
const model = $('Model Scores').first().json;
const llm = $json;
const items = c.items;

const llmMap = {};
if (Array.isArray(llm.llm_items)) for (const it of llm.llm_items) llmMap[it.id] = Number(it.score);
const modelMap = {};
if (Array.isArray(model.model_scores)) for (const s of model.model_scores) modelMap[s.id] = Number(s.score);

const perItem = items.map(a => {
  const ls = (a.id in llmMap) ? llmMap[a.id] : null;
  const ms = (a.id in modelMap) ? modelMap[a.id] : null;
  const disagree = (ls !== null && ms !== null) ? Math.abs(ls - ms) : null;
  return { item: a, llm_score: ls, model_score: ms, disagreement: disagree };
});

const mean = (arr) => {
  const v = arr.filter(x => x !== null && !Number.isNaN(x));
  return v.length ? v.reduce((a, b) => a + b, 0) / v.length : null;
};
const round = (x) => (x === null ? null : Math.round(x * 10000) / 10000);

const llmAgg = round(mean(perItem.map(p => p.llm_score)));
const modelAgg = round(mean(perItem.map(p => p.model_score)));
const disagreeAgg = round(mean(perItem.map(p => p.disagreement)));

const mag = (p) => Math.abs(p.llm_score !== null ? p.llm_score : (p.model_score !== null ? p.model_score : 0));
const top = [...perItem].sort((a, b) => mag(b) - mag(a)).slice(0, 5).map(p => ({
  headline: p.item.headline,
  source: p.item.source,
  url: p.item.url,
  language: p.item.language,
  llm_score: p.llm_score,
  model_score: p.model_score,
}));

const degraded = Boolean(llm.llm_degraded || model.model_degraded || c.degraded_fetch);
const parts = [];
if (c.degraded_fetch) parts.push(c.fetch_summary || 'news fetch degraded');
if (llm.llm_degraded) parts.push(llm.llm_reason || 'LLM scoring degraded');
if (model.model_degraded) parts.push('model scoring degraded');
let summary = llm.llm_summary || `Scored ${items.length} item(s).`;
if (parts.length) summary = 'degraded: ' + parts.join('; ') + (llm.llm_summary ? ' — ' + llm.llm_summary : '');

const output = {
  ticker: c.ticker,
  window: (c.window_minutes / 60) + 'h',
  llm_sentiment: llmAgg,
  model_sentiment: modelAgg,
  disagreement: disagreeAgg,
  n_articles: items.length,
  top_items: top,
  summary,
  status: degraded ? 'degraded' : 'ok',
};

const store_rows = perItem.map(p => ({
  id: p.item.id,
  headline: p.item.headline,
  url: p.item.url,
  source: p.item.source,
  language: p.item.language,
  published_at: p.item.published_at || null,
  llm_score: p.llm_score,
  model_score: p.model_score,
  disagreement: p.disagreement,
  raw: p.item,
}));

return [{ json: { output, store_rows, ticker: c.ticker } }];

// Persist result -> final §3.1 output. A failed write to the news table
// degrades the result rather than being silently ignored (§9.4).
const assembled = $('Compute & Assemble').first().json;
const persist = $json;
const out = { ...assembled.output };
const persistFailed = persist.error !== undefined || persist.stored === undefined;
if (persistFailed) {
  out.status = 'degraded';
  const base = out.summary || '';
  out.summary = (base.startsWith('degraded:') ? base : ('degraded: ' + base))
    + ' [persist to news table failed]';
}
return [{ json: out }];
